  1→'use client';
  2→
  3→import { useEffect, useRef, useState, useCallback } from 'react';
  4→import type { VimeoPlayerType as Player } from '@/lib/vimeo';
  5→import { loadVimeoPlayer } from '@/lib/vimeo';
  6→import { useIsMobile } from '@/lib/hooks/useIsMobile';
  7→import { usePrefersReducedMotion } from '@/lib/hooks/usePrefersReducedMotion';
  8→
  9→/**
 10→ * HERO REEL - Homepage Autoplay Video
 11→ *
 12→ * Consistency guarantees:
 13→ * 1. Deterministic initialization with timeout (12s max)
 14→ * 2. Clean error handling with fallback to static state
 15→ * 3. Proper cleanup on unmount
 16→ * 4. Scroll-based pause/resume with ref tracking
 17→ * 5. Mobile optimization: static thumbnail only (no video player)
 18→ * 6. Error event listeners for runtime failures
 19→ */
 20→
 21→// Timeout for player initialization (12 seconds - supports slow connections)
 22→const INIT_TIMEOUT_MS = 12000;
 23→
 24→interface HeroReelProps {
 25→  videoId: string;
 26→  videoHash?: string;
 27→  startTime?: number;
 28→  thumbnail?: string;
 29→}
 30→
 31→export function HeroReel({ videoId, videoHash, startTime = 0 }: HeroReelProps) {
 32→  const containerRef = useRef<HTMLDivElement>(null);
 33→  const playerRef = useRef<Player | null>(null);
 34→  const isReadyRef = useRef(false);
 35→  const scrolledDownRef = useRef(false);
 36→
 37→  const [scrollProgress, setScrollProgress] = useState(0);
 38→  const [heroRevealed, setHeroRevealed] = useState(false);
 39→  const [videoPlaying, setVideoPlaying] = useState(false);
 40→
 41→  const { isMobile, isReady: isMobileReady } = useIsMobile();
 42→  const prefersReducedMotion = usePrefersReducedMotion();
 43→
 44→  // Hero height based on device
 45→  const heroHeight = isMobile ? '50vh' : '70vh';
 46→
 47→  // Clean destroy of player instance
 48→  const destroyPlayer = useCallback(() => {
 49→    if (playerRef.current) {
 50→      try {
 51→        playerRef.current.destroy();
 52→      } catch {
 53→        // Player may already be destroyed
 54→      }
 55→      playerRef.current = null;
 56→    }
 57→    isReadyRef.current = false;
 58→  }, []);
 59→
 60→  // Reveal hero after navigation settles (creates cinematic entrance sequence)
 61→  useEffect(() => {
 62→    const revealTimer = setTimeout(() => setHeroRevealed(true), 400);
 63→    return () => clearTimeout(revealTimer);
 64→  }, []);
 65→
 66→  // Initialize Vimeo player with autoplay (desktop only)
 67→  useEffect(() => {
 68→    // Wait for mobile detection to complete before deciding
 69→    if (!isMobileReady) return;
 70→
 71→    // Skip player initialization on mobile - use static thumbnail instead
 72→    if (isMobile) return;
 73→
 74→    if (!containerRef.current) return;
 75→
 76→    const baseConfig = {
 77→      muted: true,
 78→      loop: true,
 79→      autoplay: true,
 80→      controls: false,
 81→      background: true,
 82→      responsive: true,
 83→      title: false,
 84→      byline: false,
 85→      portrait: false,
 86→      dnt: true,
 87→      playsinline: true,
 88→      quality: 'auto',
 89→      speed: true,
 90→      transparent: false, // Request dark player background from Vimeo
 91→    };
 92→
 93→    const baseUrl = videoHash
 94→      ? `https://vimeo.com/${videoId}/${videoHash}`
 95→      : `https://vimeo.com/${videoId}`;
 96→    const urlWithTime = startTime > 0 ? `${baseUrl}#t=${startTime}s` : baseUrl;
 97→
 98→    let isMounted = true;
 99→
100→    const initPlayer = async () => {
101→      try {
102→        const VimeoPlayer = await loadVimeoPlayer();
103→        if (!isMounted || !containerRef.current) return;
104→
105→        playerRef.current = new VimeoPlayer(containerRef.current!, {
106→          url: urlWithTime as `https://vimeo.com/${string}`,
107→          ...baseConfig
108→        });
109→
110→        // Race between ready() and timeout
111→        const readyPromise = playerRef.current.ready();
112→        const timeoutPromise = new Promise<never>((_, reject) => {
113→          setTimeout(() => reject(new Error('HeroReel initialization timeout')), INIT_TIMEOUT_MS);
114→        });
115→
116→        await Promise.race([readyPromise, timeoutPromise]);
117→
118→        if (!isMounted) {
119→          destroyPlayer();
120→          return;
121→        }
122→
123→        isReadyRef.current = true;
124→
125→        // Add error event listener for runtime failures
126→        playerRef.current.on('error', (error) => {
127→          console.error('HeroReel: Player error', videoId, error);
128→        });
129→
130→        // Wait for video to actually start rendering frames before revealing.
131→        // 'bufferend' fires when enough data is buffered to play without interruption.
132→        // 'playing' fires when playback actually begins after buffering.
133→        // Ultimate fallback: reveal after INIT_TIMEOUT_MS regardless.
134→        const revealOnce = () => {
135→          if (isMounted) setVideoPlaying(true);
136→        };
137→        playerRef.current.on('bufferend', revealOnce);
138→        playerRef.current.on('playing', revealOnce);
139→
140→        // Start playback (may already be playing via background autoplay)
141→        await playerRef.current.play().catch(() => {});
142→      } catch (err) {
143→        console.error('HeroReel: Player init failed', videoId, err);
144→        destroyPlayer();
145→      }
146→    };
147→
148→    initPlayer();
149→
150→    return () => {
151→      isMounted = false;
152→      destroyPlayer();
153→    };
154→  }, [videoId, videoHash, startTime, destroyPlayer, isMobile, isMobileReady]);
155→
156→  // Track scroll for fade and pause/resume
157→  useEffect(() => {
158→    const handleScroll = () => {
159→      const scrollY = window.scrollY;
160→      const viewportHeight = window.innerHeight;
161→      // Use appropriate hero height multiplier based on device
162→      const heroHeightValue = viewportHeight * (isMobile ? 0.5 : 0.7);
163→      const introPadding = 160;
164→      const textStartPosition = heroHeightValue + introPadding;
165→      const oneThirdViewport = viewportHeight / 3;
166→      const fadeStartScroll = textStartPosition - oneThirdViewport;
167→
168→      const fadeRange = 200;
169→      const progress = Math.max(0, Math.min((scrollY - fadeStartScroll) / fadeRange, 1));
170→      setScrollProgress(progress);
171→
172→      // Pause/resume with ref tracking for consistency (desktop only)
173→      if (!isMobile) {
174→        const hasScrolledDown = scrollY > 10;
175→
176→        if (hasScrolledDown && !scrolledDownRef.current) {
177→          scrolledDownRef.current = true;
178→          if (playerRef.current && isReadyRef.current) {
179→            playerRef.current.pause().catch(() => {});
180→          }
181→        } else if (!hasScrolledDown && scrolledDownRef.current) {
182→          scrolledDownRef.current = false;
183→          if (playerRef.current && isReadyRef.current) {
184→            playerRef.current.play().catch(() => {});
185→          }
186→        }
187→      }
188→    };
189→
190→    // Run immediately to sync initial state
191→    handleScroll();
192→
193→    window.addEventListener('scroll', handleScroll, { passive: true });
194→    return () => window.removeEventListener('scroll', handleScroll);
195→  }, [isMobile]);
196→
197→  const scrollOpacity = 1 - scrollProgress;
198→  const heroOpacity = heroRevealed ? scrollOpacity : 0;
199→  const heroScale = heroRevealed ? 1 : 1.02;
200→  const transitionDuration = prefersReducedMotion ? '0ms' : '1.2s';
201→  const transitionEasing = 'cubic-bezier(0.16, 1, 0.3, 1)';
202→
203→  // Transition strategy: opacity only animates during initial reveal, then becomes instant for scroll
204→  // This ensures scroll-driven fade is perfectly synchronized with navigation
205→  const heroTransition = heroRevealed
206→    ? `transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`
207→    : `opacity ${transitionDuration} ${transitionEasing}, transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`;
208→
209→  return (
210→    <div
211→      className="fixed top-0 left-0 right-0 w-full overflow-hidden"
212→      style={{
213→        height: heroHeight,
214→        zIndex: 0,
215→        backgroundColor: '#141414',
216→        // Exclude from view transition snapshot — prevents white flash
217→        // when Vimeo iframe is destroyed/recreated during page transitions
218→        viewTransitionName: 'hero-reel',
219→      }}
220→    >
221→      <div
222→        style={{
223→          width: '100%',
224→          height: '100%',
225→          opacity: heroOpacity,
226→          transform: `scale(${heroScale})`,
227→          filter: heroRevealed ? 'saturate(1) brightness(1)' : 'saturate(0.3) brightness(0.6)',
228→          transition: heroTransition,
229→          transformOrigin: 'center center',
230→          willChange: heroRevealed ? 'auto' : 'opacity, transform, filter'
231→        }}
232→      >
233→        {!isMobile && (
234→          // Desktop: Vimeo player container (behind thumbnail until video plays)
235→          <div
236→            ref={containerRef}
237→            className="absolute inset-0 w-full h-full"
238→            style={{
239→              backgroundColor: '#141414',
240→              zIndex: 0
241→            }}
242→          />
243→        )}
244→        {/* Dark overlay - sits ABOVE iframe, matches site background until video plays.
245→            Video emerges seamlessly from the page background. */}
246→        <div
247→          className="absolute inset-0 w-full h-full"
248→          style={{
249→            backgroundColor: '#141414',
250→            zIndex: 1,
251→            opacity: videoPlaying ? 0 : 1,
252→            transition: 'opacity 0.4s ease-out',
253→            pointerEvents: 'none'
254→          }}
255→        />
256→      </div>
257→    </div>
258→  );
259→}
