 1→/**
 2→ * Project Color System
 3→ * Each project gets a unique subtle background color variation
 4→ * Based on project type and index for visual distinction
 5→ */
 6→
 7→// Color palette based on project type
 8→const colorPalettes: Record<string, { hue: number; saturation: number }> = {
 9→  'Feature Film': { hue: 220, saturation: 8 },      // Cool blue tint
10→  'Commercial': { hue: 35, saturation: 6 },         // Warm amber tint
11→  'Music Video': { hue: 280, saturation: 7 },       // Purple tint
12→  'Video Game Cinematics': { hue: 160, saturation: 6 }, // Teal tint
13→  'Personal R&D / Portfolio Piece': { hue: 180, saturation: 8 }, // Cyan tint
14→  'Personal R&D / Demo Reel': { hue: 200, saturation: 6 }, // Sky blue tint
15→  'Commercial / Product Visualization': { hue: 45, saturation: 5 }, // Gold tint
16→  'Commercial / Superbowl': { hue: 0, saturation: 6 }, // Red tint
17→};
18→
19→// Default neutral palette
20→const defaultPalette = { hue: 0, saturation: 0 };
21→
22→/**
23→ * Generate a unique background color for a project
24→ * Returns HSL color string
25→ */
26→export function getProjectBackgroundColor(projectType?: string, index: number = 0): string {
27→  const palette = projectType ? (colorPalettes[projectType] || defaultPalette) : defaultPalette;
28→
29→  // Base lightness is 9.4% (#181818)
30→  // Add slight variation based on index
31→  const lightness = 9.4 + (index % 3) * 0.3;
32→
33→  // Apply subtle saturation
34→  const saturation = palette.saturation;
35→
36→  return `hsl(${palette.hue}, ${saturation}%, ${lightness}%)`;
37→}
38→
39→/**
40→ * Get a complementary accent color for project elements
41→ */
42→export function getProjectAccentColor(projectType?: string): string {
43→  const palette = projectType ? (colorPalettes[projectType] || defaultPalette) : defaultPalette;
44→
45→  if (palette.saturation === 0) {
46→    return '#FFB000'; // Default amber accent
47→  }
48→
49→  // Create a more saturated version for accents
50→  return `hsl(${palette.hue}, ${Math.min(palette.saturation * 4, 40)}%, 55%)`;
51→}
52→
53→/**
54→ * Get subtle border/divider color
55→ */
56→export function getProjectDividerColor(projectType?: string): string {
57→  const palette = projectType ? (colorPalettes[projectType] || defaultPalette) : defaultPalette;
58→
59→  return `hsl(${palette.hue}, ${palette.saturation}%, 18%)`;
60→}
